import { randomUUID } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const DATA_DIR = path.join(process.cwd(), 'data');
const DATA_FILE = path.join(DATA_DIR, 'books.json');

async function readAll() {
  try {
    const raw = await readFile(DATA_FILE, 'utf8');
    return JSON.parse(raw);
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function writeAll(books) {
  await mkdir(DATA_DIR, { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2));
}

export async function getBooks() {
  const books = await readAll();
  return books.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export async function getBook(id) {
  const books = await readAll();
  return books.find((b) => b.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const books = await readAll();
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: notes?.trim() ?? '',
    status: 'reading',
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await writeAll(books);
  return book;
}

export async function updateBook(id, updates) {
  const books = await readAll();
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return null;
  books[index] = { ...books[index], ...updates };
  await writeAll(books);
  return books[index];
}

export async function markFinished(id) {
  return updateBook(id, { status: 'finished', finishedAt: new Date().toISOString() });
}

